// A raid build with the blanks filled in from its spec's individual sim config, so the raid
// sim and the individual sims share one set of gear presets and defaults.
export interface RaidPlayerPreset extends RaidSimPreset<any> {
	specOptions: SpecOptions<any>;
	consumes: Consumes;
	// The individual sim's `defaults.other`, with this build's `otherDefaults` on top.
	otherDefaults: OtherDefaults;
	// The individual sim's gear presets this build may start in.
	gearPresets: Array<PresetGear>;
}

export const playerPresets: Array<RaidPlayerPreset> = naturalSpecOrder
	.map(spec => getSpecConfig(spec) as IndividualSimUIConfig<any>)
	.flatMap(config => config.raidSimPresets.map(preset => ({
		...preset,
		specOptions: preset.specOptions ?? config.defaults.specOptions,
		consumes: preset.consumes ?? config.defaults.consumes,
		otherDefaults: { ...config.defaults.other, ...preset.otherDefaults },
		gearPresets: config.presets.gear.filter(gear => !(preset.excludeGear || []).includes(gear)),
	})));

// Highest phase any build has a gear preset for; builds without one fall back to their latest.
export const LATEST_PRESET_PHASE: number = Math.max(
	...playerPresets.flatMap(preset => preset.gearPresets.map(gear => gear.phase ?? 0)));

export const implementedSpecs: Array<Spec> = [...new Set(playerPresets.map(preset => preset.spec))];
